import React, { useState, useEffect } from "react";
import "./Navbar.css";

const Navbar = ({ activePage, setActivePage }) => {
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem("darkMode") === "true";
  });

  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
    } else {
      document.body.classList.remove("dark-mode");
    }
  }, [darkMode]);

  const toggleDarkMode = () => {
    setDarkMode((prev) => {
      const newMode = !prev;
      localStorage.setItem("darkMode", newMode);
      return newMode;
    });
  };

  return (
    <nav className="navbar">
      <ul>
        <li
          className={activePage === "chat" ? "active" : ""}
          onClick={() => setActivePage("chat")}
          role="button"
        >
          💬 Chat
        </li>
        <li
          className={activePage === "youtube" ? "active" : ""}
          onClick={() => setActivePage("youtube")}
          role="button"
        >
          📺 YouTube
        </li>
        <li
          className={activePage === "wikipedia" ? "active" : ""}
          onClick={() => setActivePage("wikipedia")}
          role="button"
        >
          📖 Wikipedia
        </li>
        <li
          className={activePage === "test" ? "active" : ""}
          onClick={() => setActivePage("test")}
          role="button"
        >
          📝 Test
        </li>
      </ul>

      {/* 🔹 Dark Mode Toggle Button */}
      <button className="toggle-dark-btn" onClick={toggleDarkMode}>
        {darkMode ? "☀️ Light Mode" : "🌙 Dark Mode"}
      </button>
    </nav>
  );
};

export default Navbar;
